Audit the contract around `PaymentsClient.charge(invoice, options)` from these excerpts.

`payments/client.ts`:
```ts
export class PaymentsClient {
  async charge(invoice, options = {}) {
    const response = await fetch('/payments/charge', {
      method: 'POST',
      body: JSON.stringify({ invoiceId: invoice.id, idempotencyKey: options.idempotencyKey })
    });

    if (response.status === 402) return { status: 'card_declined', retryable: false };
    if (response.status === 409) return { status: 'duplicate', chargeId: response.headers.get('x-charge-id') };
    if (response.status >= 500) throw new Error('payments unavailable');
    if (!response.ok) throw new Error('charge failed');
    return response.json();
  }
}
```

`billing/finalizeInvoice.ts`:
